const unsigned g_flexShaderBlobCount = 66;

const FlexShaderBlob* findFlexShader(const char* symbol)
{
    if (symbol == nullptr)
        return nullptr;

    for (unsigned i = 0; i < 66; ++i)
    {
        if (std::strcmp(g_flexShaderBlobs[i].symbol, symbol) == 0)
            return &g_flexShaderBlobs[i];
    }
    return nullptr;
}
